// === NAME - DESCRIPTION: Integrated Math 1 1-47: Determine if a relationship is a function ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
$isFunction = rand(0,1);
$n = rand(4,5);
$xvals = array();
$yvals = array();
$needed = $isFunction ? $n : $n-1;
while (count($xvals) < $needed) {
    $x = rand(-5,5);
    if (!in_array($x, $xvals)) $xvals[] = $x;
}
if (!$isFunction) {
    $dupIdx = rand(0, $needed-1);
    $xvals[] = $xvals[$dupIdx];
}
$pairsStr = "";
for ($i=0;$i<$n;$i++) {
    $y = rand(-5,5);
    if (!$isFunction && $i == $n-1) {
        $firstY = $yvals[$dupIdx];
        while ($y == $firstY) {
            $y = rand(-5,5);
        }
    }
    $yvals[] = $y;
    if ($i>0) $pairsStr .= ", ";
    $pairsStr .= "($xvals[$i], $y)";
}
$relation = "{$pairsStr}";
$answer = $isFunction ? 0 : 1;
$questions = array("Yes","No");
$anstypes = "choices";

// === QUESTION TEXT ===
Determine whether the following relationship is a function: `{$relation}` $answerbox

// === ANSWER ===
$solutionguide = 'A relationship is a function if every input (x-value) corresponds to exactly one output (y-value). In the given relation `{$relation}`, ';
if ($isFunction) {
    $solutionguide .= 'all x-values are distinct, so each input has exactly one output. Therefore, the relationship is a function.';
} else {
    $solutionguide .= 'the x-value ' . $xvals[$dupIdx] . ' appears twice with different y-values (' . $yvals[$dupIdx] . ' and ' . $yvals[$n-1] . '), so the relationship is not a function.';
}
$solutionguide .= ' Answer: ' . ($isFunction ? 'Yes' : 'No') . '.';

// === NAME - DESCRIPTION: bar-graph-counts-versus-percentages - Bar Graph of Counts Versus Percentages: recover group size, compute one percentage, and explain why percentages preserve shape ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$anstypes = "number,number,choices";
$answer[0] = 24;
$answer[1] = 50;
$answer[2] = 0;
$questions[2] = array(
  "Because the percentages are proportional to the counts.",
  "Because the counts were rounded to whole numbers.",
  "Because the categories are different.",
  "Because the total group size changed."
);

// === QUESTION TEXT ===
<p>Part (a) The category table shows counts: Category A has 8, Category B has 12, and Category C has 4. What is the total group size N? $answerbox[0]</p>
<p>Part (b) What is the percentage of the group that is in Category B? $answerbox[1]</p>
<p>Part (c) A bar graph of the same data is drawn once with counts and once with percentages. Why does the shape of the graph stay the same? $answerbox[2]</p>

// === ANSWER ===
$solutionguide = 'Part (a) The total group size is the sum of the counts: 8 + 12 + 4 = 24. Part (b) The percentage is (12 / 24) * 100 = 50%. Part (c) The shape stays the same because percentages are proportional to counts, so the relative lengths of the bars are unchanged.';

// === NAME - DESCRIPTION: Independence Expected Counts for a 2x2 Table - Compute three expected cells from row and column totals ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$n = rand(10,20);
$N = 20*$n;
$a = rand(3, $n-3);
$b = rand(3, $n-3);
$R1 = 20*$a;
$R2 = $N - $R1;
$C1 = 20*$b;
$C2 = $N - $C1;
$E11 = $R1*$C1/$N;
$E12 = $R1*$C2/$N;
$E21 = $R2*$C1/$N;
$E22 = $R2*$C2/$N;
$L = max(1, $C1 - $R2 + 1, $R1 - $C2 + 1);
$U = min($R1, $C1) - 1;
$O11 = rand($L, $U);
$O12 = $R1 - $O11;
$O21 = $C1 - $O11;
$O22 = $R2 - $O21;
$anstypes = "number,number,number";
$answer[0] = $E11;
$answer[1] = $E12;
$answer[2] = $E21;

// === QUESTION TEXT ===
<p>A researcher classifies ' . '' . 'a sample of ' . $N . ' cases by two categorical variables, A and B, and records the observed counts below.</p>

<table style="border-collapse:collapse; margin:12px 0;">
<tr>
  <th style="border:1px solid #333; padding:5px 12px;"></th>
  <th style="border:1px solid #333; padding:5px 12px;">B: Yes</th>
  <th style="border:1px solid #333; padding:5px 12px;">B: No</th>
  <th style="border:1px solid #333; padding:5px 12px;">Total</th>
</tr>
<tr>
  <th style="border:1px solid #333; padding:5px 12px; text-align:left;">A: Yes</th>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$O11</td>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$O12</td>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$R1</td>
</tr>
<tr>
  <th style="border:1px solid #333; padding:5px 12px; text-align:left;">A: No</th>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$O21</td>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$O22</td>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$R2</td>
</tr>
<tr>
  <th style="border:1px solid #333; padding:5px 12px; text-align:left;">Total</th>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$C1</td>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$C2</td>
  <td style="border:1px solid #333; padding:5px 12px; text-align:center;">$N</td>
</tr>
</table>

<p>Assuming the two variables are independent, compute the expected count for each of the three cells below. Use the row and column totals, and enter exact values.</p>

<p><strong>a.</strong> Expected count for A = Yes and B = Yes: $answerbox[0]</p>

<p><strong>b.</strong> Expected count for A = Yes and B = No: $answerbox[1]</p>

<p><strong>c.</strong> Expected count for A = No and B = Yes: $answerbox[2]</p>

/// [QUESTION 2]

<p>What is the expected count for the remaining cell, A = No and B = No?</p>

<p>$answerbox[3]</p>

// === ANSWER ===
$solutionguide = '<p>For any cell of a two-way table, the expected count under independence is</p>
<p style="text-align:center">expected = row total &times; column total / grand total</p>
<p>The grand total here is ' . $N . '.</p>
<p><strong>a.</strong> The row total for A = Yes is ' . $R1 . ' and the column total for B = Yes is ' . $C1 . ', so</p>
<p style="text-align:center">E = ' . $R1 . ' &times; ' . $C1 . ' / ' . $N . ' = ' . $E11 . '</p>
<p><strong>b.</strong> The row total for A = Yes is ' . $R1 . ' and the column total for B = No is ' . $C2 . ', so</p>
<p style="text-align:center">E = ' . $R1 . ' &times; ' . $C2 . ' / ' . $N . ' = ' . $E12 . '</p>
<p><strong>c.</strong> The row total for A = No is ' . $R2 . ' and the column total for B = Yes is ' . $C1 . ', so</p>
<p style="text-align:center">E = ' . $R2 . ' &times; ' . $C1 . ' / ' . $N . ' = ' . $E21 . '</p>
<p>The remaining cell has expected count ' . $E22 . ', which also equals ' . $N . ' minus the other three expected counts.</p>';

// === NAME - DESCRIPTION: Critical z - right-tail area to left area for invNorm, critical z, and middle-percent z ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
loadlibrary("stats");
$rightTails = array(0.10, 0.05, 0.025, 0.01, 0.005);
$idx = randfrom($rightTails);
$alpha = $idx;
$leftArea = 1 - $alpha;
$critZ = invnormalcdf($leftArea, 0, 1);
$middlePct = (1 - 2*$alpha) * 100;
$middleZ = invnormalcdf(1 - $alpha, 0, 1); // same as $critZ

$answer[0] = $leftArea;
$answer[1] = $critZ;
$answer[2] = $middleZ;

$anstypes = array("number", "number", "number");
$tolerance = array(0.001, 0.01, 0.01);

// === QUESTION TEXT ===
For a standard normal distribution, suppose you want the critical value `z_α` for a right-tail area of `α = `$alpha`.

(a) What left-tail area do you enter into `invNorm` to obtain this critical value?  
`invNorm(` $answerbox[0] `, 0, 1)`

(b) Find the critical value `z_α`.  
`z_α = ` $answerbox[1]

(c) This same `z`-value also bounds the middle `$middlePct`% of the standard normal curve.  
Enter that `z`-value: $answerbox[2]

// === ANSWER ===
$solutionguide = '
<details><summary>Solution Guide</summary>
<p><strong>Part (a):</strong> The <code>invNorm</code> function on calculators (and in software) requires the <em>left-tail</em> (cumulative) area. For a right-tail area of `α = `$alpha`, the left-tail area is `1 - α = 1 - `$alpha` = `$leftArea`.</p>

<p><strong>Part (b):</strong> Using <code>invNorm(`$leftArea`, 0, 1)</code> gives the critical value `z_α ≈ `$critZ`.</p>

<p><strong>Part (c):</strong> The critical value `z_α` leaves area `α` in the right tail and, by symmetry, area `α` in the left tail. The remaining middle area is `1 - 2α = `$middlePct`%`. The `z`-score that bounds this middle percentage (i.e., the upper boundary) is exactly the same `z_α ≈ `$middleZ`.</p>
</details>
';

// === NAME - DESCRIPTION: Classify study design, identify bias/confounding, and state justified conclusions ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$scenarios = array(
  array(
    "desc" => "A researcher wants to know whether drinking green tea daily reduces the risk of heart disease. She recruits 500 adults and asks them to report how many cups of green tea they drink per day. She then follows them for 10 years and records which participants develop heart disease.",
    "studyClass" => "observational",
    "biases" => array("confounding by overall health consciousness green tea drinkers may also exercise more eat better or avoid smoking", "self-report bias in tea consumption", "healthy user bias"),
    "justified" => "an association between green tea consumption and heart disease risk",
    "notJustified" => "that drinking green tea causes a reduction in heart disease risk"
  ),
  array(
    "desc" => "A pharmaceutical company tests a new cholesterol-lowering drug. They randomly assign 400 volunteers with high cholesterol to either receive the new drug or a placebo. Neither the participants nor the researchers know who receives which treatment. After 6 months, they compare the average cholesterol reduction between the two groups.",
    "studyClass" => "experimental",
    "biases" => array("non-compliance or dropout differing between groups", "placebo effect", "measurement bias if blinding is broken"),
    "justified" => "that the drug causes a greater reduction in cholesterol than a placebo",
    "notJustified" => "that the drug reduces heart attacks or extends life the study only measured cholesterol not clinical outcomes"
  ),
  array(
    "desc" => "A school district surveys all 11th-grade students about their sleep habits and then obtains their GPAs from school records. They find that students who report sleeping 8 or more hours per night have higher GPAs on average than those who sleep less.",
    "studyClass" => "observational",
    "biases" => array("confounding by socioeconomic status parental involvement or general health", "reverse causation better students may have more structured schedules allowing more sleep", "self-report bias in sleep duration"),
    "justified" => "an association between reported sleep duration and GPA",
    "notJustified" => "that sleeping more causes higher grades"
  )
);
$idx = rand(0, count($scenarios) - 1);
$sc = $scenarios[$idx];
$desc = $sc["desc"];
$studyClass = $sc["studyClass"];
$biases = $sc["biases"];
$justified = $sc["justified"];
$notJustified = $sc["notJustified"];
$classAccept = ($studyClass == "observational") ? "observational or experimental" : "experimental or observational";
$studyType = ($studyClass == "observational") ? "observational" : "experimental";
if ($studyClass == "observational") {
  $guideA = "The researcher merely observes and records data without imposing any treatment or intervention. Participants choose their own exposure green tea consumption sleep habits etc";
} else {
  $guideA = "The researcher actively imposes a treatment drug notification etc by randomly assigning participants to different conditions Random assignment is the hallmark of an experiment";
}

// === QUESTION TEXT ===
<p>A researcher conducts the following study:</p>
<p><strong>`$desc`</strong></p>

<p><strong>Part (a)</strong> Is this study observational or experimental?</p>
<p>Answer: $answerbox[0]</p>

<p><strong>Part (b)</strong> Name a plausible source of bias or confounding in this study.</p>
<p>Answer: $answerbox[1]</p>

<p><strong>Part (c)</strong> Based on this study design, what conclusion <strong>IS</strong> justified?</p>
<p>Answer: $answerbox[2]</p>

<p><strong>Part (d)</strong> Based on this study design, what conclusion is <strong>NOT</strong> justified?</p>
<p>Answer: $answerbox[3]</p>

// === ANSWER ===
$anstypes = array("string", "essay", "essay", "essay");
$answer[0] = $classAccept;
$answer[1] = "";
$answer[2] = "";
$answer[3] = "";

$strflags[0] = "ignore_case,trim_whitespace";

$solutionguide = "<details><summary><strong>Solution Guide</strong></summary>";
$solutionguide .= "<p><strong>Study:</strong> " . $desc . "</p>";
$solutionguide .= "<p><strong>Part (a):</strong> This is an <strong>" . $studyType . "</strong> study. " . $guideA . "</p>";
$solutionguide .= "<p><strong>Part (b) — Plausible sources of bias/confounding:</strong></p>";
$solutionguide .= "<ul>";
$solutionguide .= "<li>" . $biases[0] . "</li>";
$solutionguide .= "<li>" . $biases[1] . "</li>";
$solutionguide .= "<li>" . $biases[2] . "</li>";
$solutionguide .= "</ul>";
$solutionguide .= "<p><strong>Part (c) — Conclusion that IS justified:</strong></p>";
$solutionguide .= "<p>" . $justified . "</p>";
$solutionguide .= "<p><strong>Part (d) — Conclusion that is NOT justified:</strong></p>";
$solutionguide .= "<p>" . $notJustified . "</p>";
$solutionguide .= "</details>";

// === NAME - DESCRIPTION: Regression: recognize scatter around a linear trend in a scatterplot with a line ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
$pattern = randfrom("linear,curved,none,outlier");

if ($pattern == "linear") {
  $description = "The points form a band around a straight line, with points above and below the line and no clear curve.";
  $correct = 0;
} elseif ($pattern == "curved") {
  $description = "The points follow a clear curve, rising quickly at first and then flattening out.";
  $correct = 1;
} elseif ($pattern == "none") {
  $description = "The points are scattered across the plot with no obvious direction or pattern.";
  $correct = 2;
} else {
  $description = "Most points form a band around a straight line, but one point lies well away from the others.";
  $correct = 3;
}

$questions[0] = "Yes — the points are scattered around a roughly straight line with no outliers.";
$questions[1] = "No — the points follow a clear curved pattern.";
$questions[2] = "No — there is no apparent trend.";
$questions[3] = "Yes — but one point lies well away from the others.";

$answer = $correct;

// === QUESTION TEXT ===
A scatterplot with a line drawn through it shows this pattern:

$description

Does the data show scatter around a roughly linear trend?

// === ANSWER ===
$solutionguide = 'Look at how the points sit relative to the line. A roughly linear trend means the points fall in a band around a straight line. A curved pattern or no pattern means a linear model is not appropriate. A point far from the rest is an outlier.';

// === NAME - DESCRIPTION: Evaluating Logarithms Base 2, 3, or 4 ===
// === SET QUESTION TYPE TO: number ===

// === COMMON CONTROL ===
$base = randfrom(3) + 1;
$exp = rand(1,8);
$arg = $base ** $exp;
$answer = $exp;

// === QUESTION TEXT ===
Evaluate the logarithm without a calculator:  log_{$base}($arg) = $answerbox

// === ANSWER ===
$solutionguide = "$base^$exp = $arg, so log_{$base}($arg) = $exp."

// === NAME - DESCRIPTION: Handshakes - Pairwise count among n people equals nC2; contrasts the unordered handshake count with the ordered card-exchange count and asks why the unordered count is half ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$n = rand(8,20);
$handshakes = $n*($n-1)/2;
$cards = $n*($n-1);

$anstypes = array("number","number","choices");

$answer[0] = $handshakes;
$answer[1] = $cards;

$questions[2] = array(
"A handshake is shared by the two people involved, so each pair yields one handshake, while a card goes from one person to another, so each pair yields two cards.",
"Twice as many people take part in the card exchange as take part in the handshakes.",
"Each person keeps one of the cards for themselves, so the cards are counted twice.",
"Cards are exchanged only between people who have not already shaken hands."
);
$answer[2] = 0;

// === QUESTION TEXT ===
<p>At a gathering of $n people, every pair of people shakes hands exactly once.</p>

<p>Part a: How many handshakes take place in total? $answerbox[0]</p>

<p>Later, every person gives one business card to each of the other people.</p>

<p>Part b: How many cards are handed out in total? $answerbox[1]</p>

<p>Part c: Why is the number of cards twice the number of handshakes? $answerbox[2]</p>

// === ANSWER ===
$solutionguide = 'Part a: A handshake is determined by the pair of people involved, and the order in which the two are named does not create a different handshake. So the count is the number of ways to choose 2 people from ' . $n . ', which is C(' . $n . ', 2) = ' . $n . ' times ' . ($n-1) . ' divided by 2 = ' . $handshakes . '. Part b: Each of the ' . $n . ' people gives a card to each of the other ' . ($n-1) . ' people, so the total is ' . $n . ' times ' . ($n-1) . ' = ' . $cards . '. Equivalently, each of the C(' . $n . ', 2) pairs produces 2 cards, giving 2 times ' . $handshakes . ' = ' . $cards . '. Part c: A handshake is shared by the two people involved, so each pair contributes exactly one handshake. A card goes from one specific person to another, so each pair contributes two cards, one in each direction. That is why the card count is twice the handshake count.';

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Build the eight disjoint regions of a 3-circle Venn directly, then
// compute the "given" survey totals from them. This guarantees every
// region is a non-negative whole number on every seed.
$onlyN    = rand(10, 30);   // Netflix only
$onlyH    = rand(10, 30);   // Hulu only
$onlyD    = rand(10, 30);   // Disney+ only
$nhOnly   = rand(4, 12);    // Netflix & Hulu, not Disney+
$ndOnly   = rand(4, 12);    // Netflix & Disney+, not Hulu
$hdOnly   = rand(4, 12);    // Hulu & Disney+, not Netflix
$allThree = rand(2, 8);     // all three services
$noneCount = rand(8, 25);   // none of the three

// Totals reported in the survey (pairwise counts INCLUDE the triple overlap).
$netflix  = $onlyN + $nhOnly + $ndOnly + $allThree;
$hulu     = $onlyH + $nhOnly + $hdOnly + $allThree;
$disney   = $onlyD + $ndOnly + $hdOnly + $allThree;
$netHulu  = $nhOnly + $allThree;
$netDis   = $ndOnly + $allThree;
$huluDis  = $hdOnly + $allThree;
$numSurveyed = $onlyN + $onlyH + $onlyD + $nhOnly + $ndOnly + $hdOnly + $allThree + $noneCount;

$anstypes = array("number", "number", "number");

$answer[0] = $onlyN + $onlyH + $onlyD;          // exactly one service
$answer[1] = $nhOnly + $ndOnly + $hdOnly;       // exactly two services
$answer[2] = $noneCount;                        // none of the three

// === QUESTION TEXT ===
A survey of $numSurveyed people asked which of three streaming services they subscribe to: Netflix, Hulu, and Disney+. The results are shown below.

- $netflix people subscribe to Netflix.
- $hulu people subscribe to Hulu.
- $disney people subscribe to Disney+.
- $netHulu people subscribe to both Netflix and Hulu.
- $netDis people subscribe to both Netflix and Disney+.
- $huluDis people subscribe to both Hulu and Disney+.
- $allThree people subscribe to all three services.

Use this information to answer the following.

(a) How many people subscribe to exactly one of the three services? $answerbox[0]

(b) How many people subscribe to exactly two of the three services? $answerbox[1]

(c) How many people subscribe to none of the three services? $answerbox[2]

// === ANSWER ===
$solutionguide = 'Step 1 -- Start in the center. The region inside all three circles is the number who subscribe to all three services: ' . $allThree . '.

Step 2 -- Fill the two-service-only regions. The ' . $netHulu . ' who subscribe to both Netflix and Hulu include the ' . $allThree . ' who also subscribe to Disney+, so Netflix and Hulu but not Disney+ is ' . $netHulu . ' - ' . $allThree . ' = ' . $nhOnly . '. In the same way, Netflix and Disney+ but not Hulu is ' . $netDis . ' - ' . $allThree . ' = ' . $ndOnly . ', and Hulu and Disney+ but not Netflix is ' . $huluDis . ' - ' . $allThree . ' = ' . $hdOnly . '.

Step 3 -- Fill the one-service-only regions. Netflix only is the Netflix total minus the three regions that overlap it: ' . $netflix . ' - ' . $nhOnly . ' - ' . $ndOnly . ' - ' . $allThree . ' = ' . $onlyN . '. Likewise Hulu only is ' . $onlyH . ' and Disney+ only is ' . $onlyD . '.

Step 4 -- Answer each question.
Exactly one service: ' . $onlyN . ' + ' . $onlyH . ' + ' . $onlyD . ' = ' . $answer[0] . '.
Exactly two services: ' . $nhOnly . ' + ' . $ndOnly . ' + ' . $hdOnly . ' = ' . $answer[1] . '.
None of the three: subtract everyone inside at least one circle from the total, ' . $numSurveyed . ' - (' . $onlyN . ' + ' . $onlyH . ' + ' . $onlyD . ' + ' . $nhOnly . ' + ' . $ndOnly . ' + ' . $hdOnly . ' + ' . $allThree . ') = ' . $answer[2] . '.';

// === NAME - DESCRIPTION: Addition Rule for Union Probability - compute P(A OR B) by subtracting the overlap, and recognize why adding the two rates alone overcounts ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$pA = randfrom(30,35,40,45,50);
$pB = randfrom(20,25,30,35,40);
$pBoth = randfrom(5,10,15);
$pUnion = ($pA + $pB - $pBoth)/100;
$pa = $pA/100;
$pb = $pB/100;
$pboth = $pBoth/100;

$anstypes = "number,choices";
$answer[0] = $pUnion;
$answer[1] = 0;

$questions[1] = array(
  "The students who do both are included in both groups, so adding the two percentages counts them twice.",
  "Probabilities can only be added when the events are mutually exclusive.",
  "The sum would be greater than 1, which is impossible for a probability.",
  "The students who do both are not part of either event."
);

// === QUESTION TEXT ===
At a large college, a survey of students found:

- `P(A) = $pa`: a randomly selected student is enrolled in a statistics course.
- `P(B) = $pb`: a randomly selected student works part-time.
- `P(A AND B) = $pboth`: a randomly selected student does both.

Use the addition rule: `P(A OR B) = P(A) + P(B) - P(A AND B)`.

**(a)** Find `P(A OR B)`, the probability that a randomly selected student is enrolled in statistics or works part-time (or both).

`P(A OR B) =` $answerbox[0]

**(b)** Why does simply adding the two rates, `$pa + $pb`, overcount the answer?

$answerbox[1]

// === ANSWER ===
$solutionguide = 'Step 1 - Use the addition rule: P(A OR B) = P(A) + P(B) - P(A AND B). Step 2 - Substitute: ' . $pa . ' + ' . $pb . ' - ' . $pboth . ' = ' . $pUnion . '. Step 3 - The overlap is subtracted because students who do both are inside both groups, so adding the two rates counts them twice. Answer: ' . $pUnion;

// === NAME - DESCRIPTION: Camila vs Rosa Settlement proportion above boundary ===
// === SET QUESTION TYPE TO: calculated ===

// === COMMON CONTROL ===
$n1 = rand(4,6);
$n2 = 2 * $n1;
$k1 = rand(1, $n1-1);
$k2 = 2 * $k1;
$prop = $k1 / $n1;
$answer = round($prop, 3);

// === QUESTION TEXT ===
In the Camila vs Rosa settlement data, Table 1 contains $n1 observations, of which $k1 are above the boundary. Table 2 contains $n2 observations, of which $k2 are above the boundary. (Note: $k2 = 2 * $k1, so the proportion above the boundary is the same in both tables.) 
What proportion of all observations from both tables combined are above the boundary? 
Enter your answer as a decimal rounded to three places: $answerbox

// === ANSWER ===
$solutionguide = "The combined proportion is $prop, which rounds to $answer. Since $k1/$n1 = $k2/$n2 = $prop, the overall proportion equals the same value.";

// === NAME - DESCRIPTION: Compare annual vs. monthly compound interest to find extra amount earned over years ===
// === SET QUESTION TYPE TO: calculated ===

// === COMMON CONTROL ===
loadlibrary("stats");
$principal = randfrom("1000,2000,3000,4000,5000,6000,7000,8000,9000,10000");
$annual_rate = randfrom("0.03,0.04,0.05,0.06,0.07,0.08,0.09,0.10");
